-- Temas do eixo identidade enviados no seed (98 linhas). Reexecutar substitui só esta categoria.
-- Aplica: npx supabase db query --linked -f scripts/curated-lesson-themes-identidade.sql

delete from public.curated_lesson_themes
 where category = 'identidade';


do $$
declare
  n integer;
  incompletos integer;
begin
  select count(*) into n
    from public.curated_lesson_themes
   where category = 'identidade';

  select count(*) into incompletos
    from public.curated_lesson_themes
   where category = 'identidade'
     and (
       length(btrim(title)) < 2
       or length(btrim(bible_passage)) < 1
       or length(btrim(core_lesson)) < 1
       or length(btrim(activity_suggestion)) < 1
     );

  if n <> 98 or incompletos <> 0 then
    raise exception 'Seed de identidade inválido: % temas, % incompletos.', n, incompletos;
  end if;
end;
$$;
